"""Flagrant, preventive and alternatives with 2025/2026 amendments."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
NEW='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15272.htm'
ANTI='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm'
SEX='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15487.htm'
ADI='https://portal.stf.jus.br/processos/detalhe.asp?incidente=7563157'
REVIEW='https://portal.stf.jus.br/noticias/verNoticiaDetalhe.asp?idConteudo=483244&ori=1'
SEN='https://legis.senado.leg.br/norma/528776'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(301,'Qualquer pessoa pode prender em flagrante; autoridades policiais e seus agentes têm dever legal nas hipóteses pertinentes.', ['Faculdade para povo, dever para polícia.', 'Flagrante exige situação legal, não mera desconfiança.'], 'A faculdade popular não autoriza linchamento, punição ou entrada domiciliar fora das hipóteses legítimas.', 'Pessoa presencia delito em execução e aciona polícia, podendo efetuar prisão legítima.', 'Suspeita vaga não legitima capturar vizinho por conta própria.', ['Para qualquer do povo é faculdade? Sim.', 'Para polícia é simples faculdade no texto? Não.'], 'Flagrante facultativo e obrigatório','Distinção pelo sujeito que realiza captura.')
add(302,'Flagrante compreende execução atual, término imediato, perseguição logo após e encontro logo depois com elementos de autoria.', ['Incisos I e II: cometendo ou acaba de cometer.', 'III: perseguição logo após em situação indicativa de autoria.', 'IV: encontrado logo depois com instrumentos, armas, objetos ou papéis pertinentes.'], 'Não há limite universal de 24 horas escrito para todas as modalidades; nem a expressão logo depois autoriza captura sem proximidade e contexto.', 'Autor é perseguido imediatamente após o fato e alcançado no encalço.', 'Encontro muito posterior exige outro título, não flagrante presumido só por suspeita.', ['O artigo fixa prazo universal de 24 horas? Não.', 'Inciso III exige perseguição nas condições legais? Sim.'], 'Modalidades flagranciais','Situações temporais e probatórias da captura.')
add(303,'Em crime permanente, flagrante persiste enquanto durar a permanência.', ['Cessação da permanência delimita hipótese.', 'Distinguir permanente de crime instantâneo com efeitos duradouros.', 'Entrada em casa ainda exige razões concretas da situação interior.'], 'Crime permanente não autoriza busca domiciliar baseada em boato nem elimina requisitos do ingresso.', 'Sequestro ainda em curso mantém situação flagrancial.', 'Dano já consumado com efeito duradouro não vira permanente só porque prejuízo continua.', ['Efeito duradouro torna todo crime permanente? Não.', 'O flagrante persiste durante permanência? Sim.'], 'Permanência','Prolongamento da consumação sob controle do agente.')
add(304,'Auto de flagrante registra apresentação, condutor, testemunhas, declarações com garantias e circunstâncias familiares.', ['Condutor: ouvir, assinatura, cópia do termo e recibo de entrega.', 'Seguem testemunhas e interrogatório com direito ao silêncio; assinaturas após oitivas e lavratura final.', 'Sem testemunha do crime, duas pessoas testemunham apresentação e assinam com condutor.', 'Recusa ou impossibilidade de assinatura do acusado: duas testemunhas ouvem leitura em sua presença.', 'Registrar filhos, idades, deficiência e responsável pelos cuidados.', 'Recolhimento depende hipótese legal; enviar autos ao competente quando necessário.'], 'Testemunha da apresentação não vira testemunha presencial do crime; silêncio não autoriza coerção nem condenação.', 'Crime não foi presenciado por terceiros; duas pessoas atestam apresentação e o auto distingue isso.', 'Se acusado não assina, registrar leitura e testemunhas, sem assinatura inventada.', ['Falta de testemunha do fato impede sempre o auto? Não.', 'Devem registrar informações de filhos previstas? Sim.'], 'Formalização do flagrante','Documentação com distinção das fontes e direitos.',[CF])
add(305,'Sem escrivão ou com impedimento, pessoa designada pela autoridade lavra auto após compromisso legal.', ['Designação e compromisso necessários.', 'Substituição funcional não dispensa conteúdo e garantias do auto.'], 'Não presumir que qualquer pessoa escreve validamente o auto sem designação e compromisso.', 'Autoridade designa substituto e colhe compromisso antes da lavratura.', 'Ausência do escrivão não permite omitir comunicações ou direitos.', ['Há compromisso legal? Sim.', 'Substituição elimina garantias do preso? Não.'], 'Escrivão substituto','Pessoa designada e compromissada para lavrar auto.')
add(306,'Prisão e localização são comunicadas imediatamente; auto ao juiz e nota de culpa ao preso têm prazo de até 24 horas.', ['Comunicação imediata ao juiz, MP e família ou pessoa indicada.', 'Auto ao juiz em até 24 horas da prisão; sem advogado informado, cópia integral à Defensoria.', 'Nota de culpa no mesmo prazo, assinada com motivo, condutor e testemunhas, mediante recibo.'], 'Não transformar prazo de remessa em autorização para atrasar comunicação imediata.', 'Prisão é comunicada logo e documentos entregues dentro das 24 horas.', 'Sem nome de advogado, enviar cópia integral à Defensoria, sem aguardar escolha indefinidamente.', ['Todas as comunicações podem esperar 24 horas? Não.', 'Nota de culpa tem motivo e nomes previstos? Sim.'], 'Comunicação e documentação','Deveres imediatos distintos dos documentos em 24 horas.')
add(307,'Delito na presença da autoridade ou contra ela em função exige auto com narrativa, voz de prisão, declarações e testemunhos.', ['Assinaturas e remessa imediata ao juiz competente se não for quem presidiu.', 'Direito ao silêncio permanece nas declarações.', 'Ser vítima não torna autoridade julgadora da própria causa.'], 'Presenciar fato não elimina garantias nem controle de competência.', 'Autoridade registra fato ocorrido diante dela e remete ao juiz competente.', 'Recusa do preso a declarar não permite preencher confissão fictícia.', ['Auto deve narrar o fato e voz de prisão? Sim.', 'O preso perde silêncio por agir contra autoridade? Não.'], 'Flagrante perante autoridade','Formalização específica com garantias intactas.')
add(308,'Sem autoridade no lugar da captura, preso é apresentado logo à autoridade do local mais próximo.', ['Não prolongar custódia por mera ausência de autoridade local.', 'Preservar comunicação e prazos legais.'], 'Local mais próximo não significa escolher destino distante por conveniência indevida.', 'Captura em local sem autoridade segue prontamente ao órgão mais próximo.', 'Deslocamento não reinicia automaticamente prazo contado da prisão.', ['Apresentação deve ser pronta? Sim.', 'Deslocamento reinicia prazo de 24 horas por si só? Não.'], 'Apresentação próxima','Encaminhamento célere na ausência de autoridade local.')
add(309,'Se hipótese legal permite livrar-se solto, libertação segue lavratura do auto.', ['Formalização não exige manter prisão indevida.', 'Integrar liberdade provisória e regime atual, sem confundir com absolvição.'], 'Lavrar auto não é decretar preventiva nem tornar condenação definitiva.', 'Autoridade formaliza flagrante e aplica hipótese legal de liberdade.', 'Liberdade não elimina apuração posterior legítima.', ['Auto implica condenação? Não.', 'Libertação impede sempre investigar? Não.'], 'Liberdade após formalização','Cessação da custódia sem encerrar necessariamente apuração.')
add(310,'Audiência de custódia controla legalidade e cautelares; texto de 2026 prevê videoconferência em tempo real com defesa e MP, em até 24 horas da prisão.', ['Decidir fundamentadamente: relaxar ilegalidade, converter em preventiva com requisitos e alternativas insuficientes, ou liberdade com/sem fiança.', 'Excludentes do art. 23/CP: liberdade fundamentada com comparecimento, nos termos do §1º.', 'Examinar reincidência, organização armada/milícia e arma restrita do §2º sem dispensar motivação concreta.', 'Omissão injustificada no prazo: responsabilidades; §4º integrado à interpretação das ADIs de 2023, sem resposta automática desvinculada da situação.', 'Lei 15.272/2025: examinar reiteração, violência/ameaça, liberação prévia salvo absolvição, processo pendente, fuga e risco à prova/instrução; integrar periculosidade do art. 312, §3º.', 'Lei 15.358/2026: conferir citações pendentes, intervenção efetiva, entrevista reservada e privacidade do preso, ressalvada presença do defensor.', 'Falha atribuível ao tribunal: repetir audiência inteira, sem convalidar ato incompleto; salas e meios estáveis.', 'Presencial excepcional por força maior: decisão justificada e limites do §13.'],
 'Não ensinar vídeo apenas pela regra anterior a 2026 nem certificar constitucionalidade definitiva da inovação: ADIs 7952, 7956, 7957 e 7958 discutem a Lei 15.358. Acompanhamento deve distinguir texto novo, entendimento de 2023 e decisões supervenientes.', 'Juiz controla flagrante em audiência remota com entrevista reservada e efetiva participação da defesa.', 'Falha de comunicação atribuível ao tribunal exige repetição completa; não publicar ato incompleto como audiência válida.', ['Audiência serve para condenar definitivamente? Não.', 'Falha do sistema atribuível ao tribunal permite aproveitar ato incompleto? Não.'], 'Controle de custódia','Exame judicial de legalidade, integridade e necessidade cautelar.',[NEW,ANTI,ADI,SEN])
add('310-a','Lei 15.272/2025 exige pedido judicial de coleta genética nas hipóteses qualificadas de flagrante previstas.', ['Violência ou grave ameaça, dignidade sexual, organização com armas ou crimes hediondos nos termos do caput.', 'MP ou polícia requerem ao juiz; não confundir com ordem administrativa irrestrita.', 'Preferencialmente na audiência ou em dez dias contados de sua realização.', 'Agente público treinado e cadeia de custódia legal/pericial.'], 'Distinguir do art. 300-A: hipóteses, momento e procedimento não são idênticos; não coletar de todo custodiado por automatismo.', 'Flagrante por crime enquadrado motiva requerimento ao juiz para coleta adequada.', 'Prazo de dez dias conta da audiência, não de data livremente escolhida pelo agente.', ['Pedido é dirigido ao juiz? Sim.', 'Qualquer flagrante entra automaticamente neste artigo? Não.'], 'Coleta genética judicial','Pedido nas hipóteses legais com custódia e agente treinado.',[NEW])
add(311,'Preventiva depende de decisão judicial provocada pelos legitimados, em investigação ou processo.', ['MP, querelante e assistente podem requerer.', 'Polícia representa.', 'Sem decretação geral de ofício após reforma de 2019.'], 'Converter flagrante não cria exceção universal à necessidade de provocação.', 'MP requer preventiva com fundamentos concretos e juiz aprecia.', 'Juiz não decreta cautelar máxima só por iniciativa acusatória própria.', ['Polícia decreta preventiva? Não, representa.', 'Assistente pode requerer nas condições legais? Sim.'], 'Provocação cautelar','Pedido ou representação que antecede decisão.')
add(312,'Preventiva exige prova do crime, indício suficiente de autoria e perigo concreto da liberdade, com finalidade cautelar legal.', ['Ordem pública/econômica, instrução ou aplicação da lei penal.', 'Descumprimento de medida não dispensa exame dos requisitos.', 'Fatos novos ou contemporâneos e decisão fundamentada.', 'Lei 15.272/2025: modus operandi, violência reiterada ou premeditação, organização, natureza/quantidade/variedade de drogas/armas/munições e receio fundado de reiteração.', '§4º proíbe gravidade abstrata: demonstrar perigo concretamente.'], 'Não equiparar estar investigado a culpado nem repetir gravidade do tipo como fundamento suficiente.', 'Ameaça concreta às testemunhas fundamenta risco à instrução, além dos demais requisitos.', 'Só afirmar que delito é grave não demonstra risco atual da liberdade.', ['Prova do crime basta sem perigo concreto? Não.', 'Gravidade abstrata é fundamento suficiente? Não.'], 'Perigo da liberdade','Risco cautelar demonstrado, distinto da pena.',[NEW])
add(313,'Hipóteses de admissibilidade da preventiva se somam aos requisitos concretos do art. 312, sem impor prisão automática.', ['Doloso com pena máxima superior a quatro anos; exatamente quatro não satisfaz só inciso I.', 'Condenação anterior dolosa definitiva, respeitado período depurador do CP.', 'Violência doméstica contra pessoas listadas para garantir medidas protetivas.', 'Lei 15.358/2026: organização ultraviolenta, grupo paramilitar ou milícia no contexto legal do inciso V.', 'Lei 15.487/2026: dignidade sexual contra criança/adolescente e tipos do ECA enumerados no inciso VI.', 'Identidade civil duvidosa: liberdade imediata após identificar, salvo outro fundamento.', 'Não usar preventiva para antecipar pena nem como consequência imediata de investigação ou denúncia.'], 'Não reativar inciso IV revogado. Incisos V e VI ampliam admissibilidade, não dispensam perigo, provocação e fundamentação; norma antifacção tem controle constitucional em acompanhamento.', 'Pena máxima exatamente quatro exige outra hipótese admissível, além do risco concreto, para preventiva.', 'Identificação esclarecida elimina fundamento identitário, salvo outra hipótese legítima de manutenção.', ['Pena máxima de quatro preenche sozinha inciso I? Não.', 'Novo inciso VI dispensa art. 312? Não.'], 'Admissibilidade','Porta legal somada à necessidade cautelar.',[ANTI,SEX,ADI])
add(314,'Preventiva não é decretada quando provas demonstram fato em excludente de ilicitude do art. 23, I–III, do CP.', ['Estado de necessidade, legítima defesa e estrito dever/exercício regular nas hipóteses legais.', 'Exige verificação probatória, não alegação sem análise.'], 'Alegar legítima defesa não é automaticamente provar seus requisitos.', 'Provas demonstram legítima defesa e impedem preventiva pelo artigo.', 'Versão sem suporte deve ser apreciada, sem assumir excludente só pela afirmação.', ['A regra exige verificação pelas provas? Sim.', 'Toda alegação isolada torna excludente comprovada? Não.'], 'Excludente e cautela','Limite legal quando fato é justificado.')
add(315,'Decretar, substituir ou negar preventiva exige motivação real, fatos pertinentes e resposta às questões decisivas.', ['Fatos novos ou contemporâneos concretos.', 'Não basta copiar lei, conceito vago ou motivo genérico.', 'Enfrentar argumentos capazes de infirmar conclusão.', 'Precedente: identificar razão determinante e adequação; afastamento exige distinção ou superação demonstrada.'], 'Texto longo com frases prontas pode continuar sem fundamentação.', 'Juiz explica risco atual à testemunha, prova e insuficiência da alternativa.', 'Citar súmula sem mostrar relação com caso não resolve motivação.', ['Só copiar o art. 312 fundamenta? Não.', 'Precisa explicar adequação do precedente? Sim.'], 'Fundamentação concreta','Razões individualizadas e controláveis.')
add(316,'Sem motivo subsistente, preventiva pode ser revogada; manutenção exige revisão fundamentada a cada noventa dias na fase abrangida.', ['Revogação pode ser de ofício ou a pedido.', 'Nova decretação observa provocação e requisitos atuais.', 'ADIs 6581/6582: falta de revisão não gera soltura automática; provocar reavaliação pelo juízo competente.', 'STF delimitou revisão à fase sem condenação em segunda instância, sem afastar outros controles de legalidade.'], 'Não ensinar noventa dias como prazo máximo automático da preventiva nem autorizar ignorar revisão obrigatória.', 'Juízo reavalia motivos em decisão atual e fundamentada.', 'Prazo passou sem revisão: exigir controle judicial, sem concluir liberação automática por calendário.', ['Após noventa dias há soltura automática? Não.', 'Revisão é dispensável porque não há soltura automática? Não.'], 'Reavaliação periódica','Controle obrigatório da necessidade atual.',[REVIEW])
add(317,'Prisão domiciliar recolhe acusado ou indiciado à residência, com saída só por autorização judicial.', ['Continua sendo prisão.', 'Não equivale ao simples recolhimento noturno do art. 319.'], 'Não confundir liberdade sem restrições com domiciliar.', 'Acusado cumpre prisão em casa e pede autorização para saída necessária.', 'Recolhimento apenas noturno é medida distinta, com condições próprias.', ['Domiciliar permite sair livremente? Não.', 'É igual a recolhimento noturno? Não.'], 'Prisão domiciliar','Custódia residencial sujeita a autorização para sair.')
add(318,'Substituição por domiciliar depende de hipótese e prova idônea: idade avançada, doença grave, cuidados e parentalidade nas condições legais.', ['Maior de oitenta anos, não apenas completar oitenta.', 'Extrema debilidade por doença grave.', 'Imprescindível aos cuidados de menor de seis ou pessoa com deficiência.', 'Gestante; mulher com filho menor de doze; homem único responsável por filho menor de doze.', 'Prova idônea dos requisitos; integrar art. 318-A.'], 'Não generalizar doença comum ou qualquer pai como hipótese suficiente.', 'Homem demonstra ser único responsável por filho de dez anos e pede substituição.', 'Pai sem exclusividade dos cuidados não satisfaz só inciso VI; verificar eventual outra hipótese.', ['Para homem basta ter filho menor de doze? Não.', 'Requisitos precisam de prova idônea? Sim.'], 'Hipótese domiciliar','Condição legal comprovada para substituição.')
add('318-a','Preventiva da gestante, mãe ou responsável por criança ou pessoa com deficiência é substituída nas condições legais de proteção.', ['Não ter praticado crime com violência ou grave ameaça à pessoa.', 'Não ter cometido crime contra filho ou dependente.', 'Examinar enquadramento e integração jurisprudencial, sem converter condição familiar em imunidade.'], 'Substituir preventiva não é absolver; exceções expressas precisam ser verificadas.', 'Mãe abrangida por requisitos, sem violência nem crime contra dependente, recebe análise de substituição.', 'Crime contra próprio dependente incide na exclusão expressa, sem resposta automática favorável.', ['Crime contra dependente satisfaz condição do inciso II? Não.', 'Domiciliar equivale a absolvição? Não.'], 'Proteção familiar cautelar','Substituição condicionada ao âmbito legal.')
add('318-b','Domiciliar dos arts. 318 e 318-A pode ser combinada com medidas alternativas do art. 319.', ['Cumulação deve ser adequada e fundamentada.', 'Condições adicionais não são obrigatórias em todos os casos.'], 'Domiciliar não impede monitoração cabível nem exige impor toda lista de cautelares.', 'Substituição combina domiciliar com monitoração pertinente ao risco.', 'Sem necessidade, não acumular restrições apenas para agravar situação.', ['Pode cumular medida do art. 319? Sim.', 'Toda cumulação é automática e obrigatória? Não.'], 'Cumulação adequada','Combinação de restrições justificadas.')
add(319,'Medidas diversas da prisão oferecem restrições específicas proporcionais ao risco, isoladas ou cumuladas nos termos legais.', ['Comparecimento periódico; restrição de lugares e contato com pessoa.', 'Não sair da comarca; recolhimento noturno e folgas com residência e trabalho fixos.', 'Suspender função ou atividade econômica/financeira quando risco de uso criminoso.', 'Internação provisória: violência/ameaça, conclusão pericial de inimputabilidade/semi-imputabilidade e risco de reiteração.', 'Fiança para fins legais e monitoração eletrônica.', 'Fiança segue capítulo próprio e pode cumular; §§1º–3º antigos revogados.'], 'Internação não decorre de diagnóstico isolado; não confundir recolhimento noturno com prisão domiciliar integral.', 'Risco de contato intimidatório é enfrentado por proibição concreta de contato.', 'Internação exige requisitos próprios e perícia, não simples conveniência.', ['Monitoração está na lista? Sim.', 'Doença mental isolada preenche toda internação cautelar? Não.'], 'Alternativas cautelares','Medidas específicas com necessidade e adequação.')
add(320,'Proibição de sair do país é comunicada ao controle de fronteiras e acusado é intimado a entregar passaporte em 24 horas.', ['Juiz comunica autoridades de fiscalização.', 'Entrega após intimação no prazo legal.', 'Proibição de país difere de proibição de comarca.'], 'Não concluir que reter passaporte por iniciativa administrativa sempre dispensa ordem e fundamentos.', 'Juiz impõe e comunica restrição, intimando entrega em 24 horas.', 'Medida de permanecer na comarca não é automaticamente idêntica à restrição de saída nacional.', ['Prazo de entrega é 24 horas? Sim.', 'País e comarca são a mesma restrição? Não.'], 'Restrição de saída nacional','Medida judicial com comunicação e entrega de documento.')
assert len(rows)==23
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'flagrant and preventive reviewed')
